-- Errata reading for M02: Most recent = the last result by event_time (record_id tiebreak), not the worse value of the latest day.
WITH lab AS (SELECT patient, json_extract(payload,'$.value') v, row_number() OVER (PARTITION BY patient ORDER BY json_extract(payload,'$.event_date') DESC, json_extract(payload,'$.event_time') DESC, json_extract(payload,'$.record_id') DESC) rn FROM records WHERE stream='labs' AND json_extract(payload,'$.name') IN ('eGFR','Glomerular filtration rate') AND json_extract(payload,'$.event_date') IS NOT NULL AND typeof(json_extract(payload,'$.value')) IN ('integer','real') AND coalesce(json_extract(payload,'$.result_status'),'')<>'cancelled'), last AS (SELECT patient, v FROM lab WHERE rn=1) SELECT patient AS patient_id FROM last WHERE v < 60 ORDER BY 1;
